// Echo skill descriptions (ECHO_DATA[name].desc). Echo names stay in English: no confirmed Spanish names.
/** @type {Record<string, { desc: string }>} */
export const ECHO_DATA_ES = {
  "Mourning Aix": { desc: "Un Señor supremo aviar espectral. La habilidad se transforma en Aix del Lamento para 2 ataques de garras que infligen 157 %/236 % de daño Espectro, y luego otorga +12 % de daño Espectro y +12 % de daño de liberación de resonancia durante 15 s." },
  "Feilian Beringal": { desc: "Un imponente Señor supremo simiesco envuelto en viento. La habilidad se transforma en Beringal del Bosque para una potente patada (231 % de daño Aero) y un golpe posterior (283 % de daño Aero), y luego otorga +12 % de daño Aero y +12 % de daño de ataque pesado durante 15 s." },
  "Tempest Mephis": { desc: "Un Señor supremo lupino envuelto en rayos. La habilidad se transforma en Mephis Tempestad para ataques de cola (102 % de daño Electro cada uno) y un zarpazo (175 % de daño Electro), y luego otorga +12 % de daño Electro y +12 % de daño de ataque pesado durante 15 s." },
  "Thundering Mephis": { desc: "Un enorme Señor supremo lobuno que crepita de trueno. La habilidad se transforma en Mephis Trueno para hasta 6 golpes (132 % de daño Electro cada uno, el último 189 %), y luego otorga +12 % de daño Electro y +12 % de daño de liberación de resonancia durante 15 s." },
  "Inferno Rider": { desc: "Un Señor supremo caballero montado en llamas. La habilidad se transforma en Jinete Infernal para 3 tajos que infligen 242 %/282 %/282 % de daño Fusión, y luego otorga +12 % de daño Fusión y +12 % de daño de ataque básico durante 15 s. Mantén pulsado para entrar en modo montura." },
  "Bell-Borne Geochelone": { desc: "Una tortuga gigante que carga una campana. La habilidad inflige un 145 % de daño Glacio escalado con DEF y otorga un Escudo de campana (50 % de reducción de daño, +10 % de daño para el equipo) que dura 15 s o 3 golpes." },
  "Impermanence Heron": { desc: "Un Señor supremo espectral con forma de grulla. La habilidad se transforma en Garza Impermanencia e inflige un 310 % de daño Destrucción en picado; mantén pulsado para escupir llamas (55 % de daño Destrucción cada una). Restaura 10 de energía de resonancia al impactar y aumenta un 12 % el daño del siguiente personaje durante 15 s tras el Outro." },
  "Lampylumen Myriad": { desc: "Un Señor supremo medusa luminosa de las profundidades marinas. La habilidad se transforma en Engendro de Lampilumen para 3 golpes gélidos que infligen 220 %/200 %/266 % de daño Glacio. Cada golpe otorga +4 % de daño Glacio y +4 % de daño de habilidad de resonancia durante 15 s, acumulable 3 veces." },
  "Mech Abomination": { desc: "Un grotesco Señor supremo constructo mecánico. La habilidad golpea con un 48 % de daño Electro e invoca Mech Waste, que inflige un 320 % de daño Electro al impactar (y explota con un 160 % adicional). Otorga +12 % de ATQ durante 15 s. El daño de Mech Waste cuenta como daño de habilidad Outro." },
  "Crownless": { desc: "Un Señor supremo humanoide sin rostro hecho de pura energía de Destrucción. La habilidad se transforma en Destronado para 4 ataques: dos golpes de 134 % de daño Destrucción, un golpe doble de 100 % y un golpe triple de 67 %. Otorga +12 % de daño Destrucción y +12 % de daño de habilidad de resonancia durante 15 s." },
  "Jué": { desc: "El antiguo dragón guardián de Jinzhou. La habilidad invoca a Jué para que se eleve y ataque (48 % de daño Espectro), llame a 5 rayos (19 % cada uno) y descienda en espiral dos veces (48 % cada una). Otorga la Bendición del Tiempo: +16 % de bonificación de daño de habilidad de resonancia y daño continuo Espectro durante 15 s." },
  "Fallacy of No Return": { desc: "Un Señor supremo de otro mundo que dobla la realidad. La habilidad explota en el área circundante con un 15,86 % de los PV máx. como daño Espectro; mantén pulsado para una ráfaga de 1,58 % de los PV máx. por golpe, que termina con un 19,82 % de los PV máx. Otorga +10 % de regeneración de energía y +10 % de ATQ a todo el equipo durante 20 s." },
  "Sentry Construct": { desc: "Un enorme constructo guardián acorazado. La habilidad se transforma en Constructo Guardia e inflige un 405 % de daño Glacio. Cuando suficientes liberaciones de resonancia cargan el Condensador de golpe al máximo, reinicia la reutilización del Eco y se lanza en picado con un 405 % de daño Glacio y congelación. Otorga +12 % de daño Glacio y +12 % de daño de habilidad de resonancia." },
  "Nightmare: Impermanence Heron": { desc: "Una variante pesadilla de la grulla espectral envuelta en energía prismática. La habilidad se transforma y asesta hasta 10 golpes de 40 % de daño Destrucción cada uno. En la ranura principal otorga pasivamente +12 % de daño Destrucción y +12 % de daño de ataque pesado." },
  "Nightmare: Lampylumen Myriad": { desc: "Una variante pesadilla de la medusa luminosa. La habilidad se transforma y ataca a los enemigos circundantes con un 273 % de daño Glacio. En la ranura principal otorga pasivamente +12 % de daño Glacio y +30 % de daño de ataque coordinado." },
  "Dragon of Dirge": { desc: "Un dragón afligido de las profundidades de Rinascita. La habilidad se transforma e invoca una Grieta de duelo que dura 5 s y que inflige periódicamente un 36 % de daño Fusión a los enemigos del área. En la ranura principal otorga +12 % de daño Fusión y +12 % de daño de ataque básico." },
  "Nightmare: Hecate": { desc: "Una variante pesadilla de la bruja de tres cabezas de las profundidades. La habilidad se transforma en Nightmare Hecate, salta y se estrella en 3 fases de daño Destrucción (152 % cada una). En la ranura principal otorga pasivamente +12 % de daño Destrucción y +20 % de daño de habilidad de Eco." },
  "Nightmare: Crownless": { desc: "Una variante pesadilla del Señor supremo sin rostro de Destrucción. La habilidad se transforma y ataca a los enemigos de enfrente con un 405 % de daño Destrucción. 3 cargas (1 cada 12 s). Al impactar, +20 % de daño durante 2 s. En la ranura principal otorga +12 % de daño Destrucción y +12 % de daño de ataque básico." },
  "Nightmare: Mourning Aix": { desc: "Una variante pesadilla del ave espectral. La habilidad invoca a Pesadilla: Aix del Lamento, que inflige un 273 % de daño Espectro. El daño a enemigos con Espectro estridente aumenta un 100 %. En la ranura principal otorga +12 % de daño Espectro." },
  "Nightmare: Feilian Beringal": { desc: "Una variante pesadilla del simio del viento. La habilidad invoca a Pesadilla: Beringal del Bosque, que inflige un 164 % de daño Aero y deja un Haz de torbellino que ataca 5 veces más con un 21 % de daño Aero cada una. En la ranura principal otorga +12 % de daño Aero y +12 % de daño de ataque pesado." },
  "Nightmare: Inferno Rider": { desc: "Una variante pesadilla del caballero en llamas. La habilidad se transforma y salta para atacar con un 405 % de daño Fusión. Mantén pulsado para entrar en modo montura (al salir inflige un 283 % de daño Fusión). En la ranura principal otorga +12 % de daño Fusión y +12 % de daño de habilidad de resonancia." },
  "Nightmare: Tempest Mephis": { desc: "Una variante pesadilla del lobo del rayo. La habilidad se transforma y ataca a los enemigos circundantes con un 405 % de daño Electro. En la ranura principal otorga +12 % de daño Electro y +12 % de daño de habilidad de resonancia." },
  "Nightmare: Thundering Mephis": { desc: "Una variante pesadilla del lobo del trueno. La habilidad se transforma y ataca a los enemigos de enfrente con un 405 % de daño Electro. En la ranura principal otorga +12 % de daño Electro y +12 % de daño de liberación de resonancia." },
  "Dreamless": { desc: "Una Calamidad humanoide de pura Destrucción ligada al pasado del Errante. La habilidad se transforma para 6 golpes: los primeros 5 infligen un 54 % de daño Destrucción cada uno y el último un 270 %. El daño aumenta un 50 % durante los 5 s posteriores a la liberación de resonancia de Rover: Havoc." },
  "Reminiscence: Fleurdelys": { desc: "Un eco del antiguo dragón-flor guardián. La habilidad invoca al Rompevientos para 8 golpes de 27 % de daño Aero más un golpe de 136 % de daño Aero. En la ranura principal otorga +10 % de daño Aero (+20 % si el portador es Rover: Aero o Cartethyia)." },
  "Lioness of Glory": { desc: "Un orgulloso Señor supremo leonino que empuña la Alabarda de la Gloria. La habilidad invoca la Alabarda para aplastar un área con un 82 % de daño Fusión y luego sale despedida con un 191 % de daño Fusión. En la ranura principal otorga +12 % de daño Fusión y +12 % de daño de liberación de resonancia." },
  "The False Sovereign": { desc: "Un Señor supremo rey marioneta imbuido de Electro. La habilidad se transforma y se lanza hacia delante con un golpe giratorio que inflige un 55 % de daño Electro x4. Al lanzar la habilidad Intro, también invoca al Falso Soberano para un 405 % de daño Electro. En la ranura principal otorga +12 % de daño Electro y +12 % de daño de ataque pesado. 2 cargas, 1 cada 8 s." },
  "Lady of the Sea": { desc: "Un majestuoso Señor supremo marítimo que controla las mareas. La habilidad invoca una Tormenta de marea que inflige un 13 % de daño Aero x10 y un 164 % de daño Aero x1. En la ranura principal otorga +12 % de daño Aero y +12 % de daño de liberación de resonancia." },
  "Corrosaurus": { desc: "Un raro saurio acorazado de las Mesetas Sanguis que escupe roca fundida. La habilidad invoca a Corrosaurio para atacar con un 273 % de daño Fusión. En la ranura principal otorga +12 % de daño Fusión y +20 % de daño de habilidad de Eco." },
  "Reminiscence: Threnodian - Leviathan": { desc: "Una colosal Calamidad marina envuelta en Destrucción. La habilidad invoca un Horizonte en colapso para 2 golpes de 131 % de daño Destrucción y crea un Núcleo de colapso durante 15 s (24 % de daño Destrucción por golpe, hasta 8 veces). En la ranura principal otorga +12 % de daño Destrucción y +12 % de daño de liberación de resonancia." },
  "Hyvatia": { desc: "Un antiguo jefe constructo de Lahai-Roi que dispara láseres convergentes. La habilidad invoca a Hyvatia en el aire para disparar láseres que infligen un 27 % de daño Espectro x10. Un Outro en los siguientes 15 s otorga al Resonador entrante +10 % de bonificación de daño de todos los atributos durante 15 s." },
  "Twin Nova - Nebulous Cannon": { desc: "El modelo a distancia de una pareja de mechas de combate del Colectivo Spacetrek. La habilidad se transforma para cortar a los enemigos dos veces con un 80 % de daño Espectro cada una. En la ranura principal otorga +12 % de daño Espectro y +12 % de daño de ataque básico. Emparejado con Collapsar Blade permite ataques combinados y acumulaciones de Dyad Origins (+10 % de daño de habilidad de Eco cada una, hasta 6)." },
  "Sigillum": { desc: "Un guardián estelar de clase Calamidad sellado más allá de la Puerta de la Estrella Perdida. La habilidad invoca a Sigillum para dos ataques que infligen 68 %/205 % de daño Fusión. Equipado por Aemeath, otorga +25 % de daño de liberación de resonancia." },
  "Reactor Husk": { desc: "Un enorme constructo reactor de Lahai-Roi. La habilidad se transforma en Coraza del Reactor, salta por los aires y descarga un tajo pesado que inflige un 351 % de daño Fusión. Otorga +10 % de regeneración de energía." },
  "Nameless Explorer": { desc: "Un misterioso Señor supremo explorador que vaga entre ruinas olvidadas. La habilidad invoca a Explorador Sin Nombre para atacar a los enemigos a su paso con un 273,6 % de daño Aero. Otorga +12 % de daño Aero y +20 % de daño de habilidad de Eco." },
  "Lorelei": { desc: "Un Señor supremo similar a una sirena que atrae con melodías inquietantes. La habilidad se transforma en Lorelei y entona un Treno de la ruina que inflige un 68 % de daño Destrucción x6 a los enemigos en un cono. Los enemigos alcanzados por las 6 notas quedan Silenciados 2 s. Otorga +12 % de daño Destrucción y +12 % de daño de liberación de resonancia." },
  "Nightmare: Kelpie": { desc: "Una variante pesadilla de un Señor supremo caballo de agua envuelto en niebla helada. La habilidad se transforma en Pesadilla: Kelpie para atacar a los objetivos cercanos con un 405 % de daño Glacio. Al cambiar de personaje con la habilidad Outro, se invoca de nuevo e inflige un 405 % de daño Aero. Otorga +12 % de daño Glacio y +12 % de daño Aero." },
  "Hecate": { desc: "La Calamidad bruja de tres cabezas de las profundidades. La habilidad invoca 3 Siervos creciente que giran y atacan a los enemigos con cuchillas giratorias con un 45,6 % de daño Destrucción; activar un Contraataque reinicia su duración. Otorga +40 % de daño de ataque coordinado." },
  "Reminiscence: Fenrico": { desc: "Una reminiscencia del lobo guardián Fenrico, que aúlla con viento primigenio. La habilidad invoca las Garras del Decreto para atacar a los enemigos cercanos con un 273,6 % de daño Aero. Otorga +12 % de daño Aero y +12 % de daño de ataque pesado." },
  "Thousand-Puppet Pavilion": { desc: "Un constructo maestro de marionetas de clase Calamidad de la Tierra de Xuanfang. La habilidad ataca a los enemigos cercanos con un 109,44 % de daño Destrucción e invoca 4 Hojas de los Mil Recuerdos (15 s); infligir Ruina de destrucción consume una Hoja para infligir un 41,04 % de daño Destrucción (una vez por segundo). En la ranura principal otorga +12 % de daño Destrucción y +12 % de daño de ataque pesado." },
  "Myriad Snare: Rustfire Chassis": { desc: "Un peligro mecánico de clase Señor supremo de la Tierra de Xuanfang. La habilidad invoca un chasis aplastante que inflige un 10,20 % de los PV máx. como daño Fusión al impactar y hasta 19 golpes más de 0,37 % de los PV máx. de daño Fusión cada uno. En la ranura principal otorga +12 % de daño Fusión y +12 % de daño de ataque pesado." },
  "Reminiscence: Denia": { desc: "El Eco distintivo de clase Calamidad de Denia. La habilidad invoca a «Trickster» para un 273,60 % de daño Fusión; en los siguientes 15 s, lanzar la habilidad Outro otorga al Resonador entrante +12 % de bonificación de daño Fusión durante 15 s." },
  "Reminiscence: Threnodian - Voidborne Construct": { desc: "Un Eco de clase Calamidad de la Tierra de Xuanfang. La habilidad invoca la Creación de Aleph-1 para 5 golpes de 21,88 % de daño Glacio más un golpe de 164,16 % de daño Glacio. En la ranura principal otorga +12 % de daño Glacio y +12 % de daño de liberación de resonancia." },
  "Reminiscence - Nightmare: Adam Smasher": { desc: "Un Eco de clase Señor supremo de la colaboración con Cyberpunk: Edgerunners. La habilidad inflige 16 golpes de 10,26 % de ATQ como daño Físico. Equipado en la ranura principal por Lucy o Rebecca, otorga +15 % de tasa crítica y desbloquea una habilidad de Eco mejorada específica del personaje (Lucy: ráfaga Espectro; Rebecca: lluvia de misiles Electro)." },
  "Calamity Effigy": { desc: "Un Eco de clase Calamidad de la Tierra de Xuanfang, el Eco principal exclusivo de Qingxiao. La habilidad se transforma para infligir daño Aero; la ranura principal otorga bonificación de daño Aero." },
  "Forbidden Bastion": { desc: "Un constructo fortificado de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Bastión Prohibido para golpear a los enemigos con un 237,60 % de daño Glacio. La ranura principal otorga +10 % de bonificación de curación." },
  "Fog Lionarch": { desc: "Una bestia de clase Élite de la Tierra de Xuanfang. La habilidad invoca a León Neblinoso para escupir fuego a los enemigos e infligir 7 fases de 33,93 % de daño Fusión." },
  "Voidwing Moth": { desc: "El Eco polilla de clase Élite emparejado de Denia. La habilidad se transforma en Polilla de Vacío para un 405 % de daño Espectro al lanzarla, o mantén pulsado para hasta 12 golpes de 49,33 % de daño Espectro. En los siguientes 15 s, lanzar la habilidad Outro otorga al Resonador entrante +12 % de ATQ durante 15 s." },
  "Capitaneus": { desc: "El comandante supremo de la Orden, que ejecuta el juicio sobre los transgresores. La habilidad invoca a Capitaneus para saltar y estrellarse con un 118 % de daño Espectro, generando 4 Juicios despiadados de 59 % de daño Espectro cada uno. En la ranura principal otorga +12 % de daño Espectro y +12 % de daño de ataque pesado." },
  "Havoc Dreadmane": { desc: "Una bestia leonina de melena oscura que irradia energía de Destrucción. La habilidad se transforma en Lobo de Destrucción para 2 golpes de cola, cada uno con un 116 % de daño Destrucción más un 77 % adicional de daño Destrucción al impactar." },
  "Lumiscale Construct": { desc: "Un constructo acorazado de escamas luminosas. La habilidad adopta una Postura de parada; el tajo inflige un 553 % de daño Glacio, o el contraataque al impactar inflige 553 % + 276 % de daño Glacio." },
  "Tambourinist": { desc: "Una Discordia Tácita humanoide rítmica que convierte el sonido en arma. La habilidad invoca a Panderista tocando Melodías de aniquilación; cuando un Resonador golpea a un objetivo, inflige un 14 % de daño Destrucción hasta 10 veces durante 10 s." },
  "Spearback": { desc: "Una feroz bestia parecida a un oso cubierta de espinas de tacetita con forma de flecha. La habilidad invoca a Osezno Aflechado para 5 ataques: los primeros 4 infligen un 29 % de daño Físico cada uno y el último un 51 % de daño Físico." },
  "Carapace": { desc: "Un constructo de élite que se camufla entre las ruinas de la ciudad. La habilidad se transforma en Caparazón para un ataque giratorio (112 % de daño Aero) seguido de un tajo (168 % de daño Aero)." },
  "Roseshroom": { desc: "Una Discordia Tácita fúngica madura que canaliza energía oscura por su sombrero. La habilidad invoca a Champirosa para disparar un láser que inflige un 57 % de daño Destrucción hasta 3 veces." },
  "Violet-Feathered Heron": { desc: "Una garza de alas moradas que solo despliega sus alas durante las tormentas eléctricas. La habilidad adopta una Postura de parada; el contraataque inflige un 288 % de daño Electro. Si es atacada durante la parada, contraataca antes y recupera 5 de energía de Concierto." },
  "Cyan-Feathered Heron": { desc: "Una garza de alas cian que habita en bosques y costas. La habilidad se transforma y carga contra los enemigos infligiendo un 236 % de daño Aero e interrumpiendo sus habilidades especiales al impactar." },
  "Flautist": { desc: "Una Discordia Tácita humanoide que empuña el sonido como arma. La habilidad se transforma y emite continuamente láseres Electro que infligen un 53 % de daño Electro x10. Obtiene 1 de energía de Concierto por golpe." },
  "Hoochief": { desc: "Una gran Discordia Tácita primate que domina el viento. La habilidad se transforma en Jefemico Cyclone y golpea a los enemigos con un 268 % de daño Aero." },
  "Stonewall Bracer": { desc: "Un corpulento constructo con armadura de piedra. La habilidad se transforma y carga hacia delante con un 112 % de daño Físico, luego golpea con un 168 % de daño Físico y obtiene un escudo igual al 10 % de los PV máx. durante 7 s." },
  "Autopuppet Scout": { desc: "Una marioneta de combate abandonada que se esconde en las ruinas de la ciudad. La habilidad se transforma e inflige un 272 % de daño Glacio a los alrededores y genera hasta 3 Muros de hielo que bloquean a los enemigos." },
  "Viridblaze Saurian": { desc: "Una gran bestia anfibia de los bosques que escupe fuego. La habilidad invoca a Saurio Viridblaze para exhalar fuego de forma continua e infligir un 17 % de daño Fusión x10." },
  "Glacio Dreadmane": { desc: "Una bestia leonina helada del Monte Firmamento. La habilidad desgarra a los enemigos con un 214 % de daño Glacio y tiene 2 cargas. Inflige +20 % de daño en el aire y genera 6 Carámbanos al aterrizar (32 % de daño Glacio cada uno)." },
  "Chasm Guardian": { desc: "Un constructo rocoso del abismo, creado para aplastar más que para proteger. La habilidad se transforma para un Golpe de salto que inflige un 273 % de daño Destrucción a costa del 10 % de PV, y luego restaura hasta un 10 % de los PV máx. durante 5 s." },
  "Abyssal Mercator": { desc: "Un combatiente curtido de las profundidades. La habilidad se transforma en Mercator Abisal para invocar 3 Púas de hielo que infligen un 89,39 % de daño Glacio cada una a los enemigos." },
  "Twin Nova - Collapsar Blade": { desc: "El modelo cuerpo a cuerpo de una pareja de mechas de combate del Colectivo Spacetrek. La habilidad se transforma para disparar rápidamente a los enemigos durante 5 s, con ataques de 2,01 % de daño Electro cada uno. En la ranura principal otorga +12 % de daño Electro y +12 % de daño de ataque básico. Emparejado con Nebulous Cannon permite ataques combinados y acumulaciones de Dyad Origins (+10 % de daño de habilidad de Eco cada una, hasta 6)." },
  "Sabercat Prowler": { desc: "Un sigiloso depredador felino de Lahai-Roi. La habilidad invoca a Merodeador Félido para disparar haces a los enemigos e infligir un 192,6 % de daño Destrucción." },
  "Sabercat Reaver": { desc: "Un feroz combatiente felino de Lahai-Roi. La habilidad invoca a Saqueador Félido para atacar a los enemigos e infligir un 192,6 % de daño Fusión." },
  "Spacetrek Explorer": { desc: "Una unidad de apoyo espacial del Colectivo Spacetrek. La habilidad invoca a Explorador Intergaláctico para otorgar a los miembros del equipo activos cercanos un Escudo igual al 10 % de los PV máx. del invocador durante 4 s." },
  "Flora Reindeer": { desc: "Una gentil criatura parecida a un reno de Lahai-Roi. La habilidad invoca a Reno Floral para atacar a los enemigos en un área amplia e infligir un 192,6 % de daño Aero." },
  "Windlash Coleoid": { desc: "Una criatura cefalópoda imbuida de viento. La habilidad se transforma en Coleoide Vendaval para patear a los enemigos e infligir un 268,2 % de daño Aero." },
  "Frostbite Coleoid": { desc: "Una criatura cefalópoda imbuida de escarcha. La habilidad invoca a Coleoide Escarchado para golpear a los enemigos e infligir un 192,6 % de daño Glacio." },
  "Glommoth": { desc: "Una criatura luminosa parecida a una polilla de Lahai-Roi. La habilidad invoca a Glamut para pisotear a los enemigos e infligir un 273,6 % de daño Glacio. Lanzar la habilidad Outro en los siguientes 15 s otorga al Resonador entrante +12 % de bonificación de daño Glacio durante 15 s." },
  "Ironhoof": { desc: "Una pesada bestia con pezuñas de Lahai-Roi. La habilidad se transforma en Pezuña Férrea para cargar contra los enemigos e infligir un 53,6 % de daño Fusión. Al final de la carga, una cornada inflige un 13,4 % de daño Fusión 3 veces y un 174,3 % de daño Fusión una vez." },
  "Mining Reindeer": { desc: "Una criatura parecida a un reno usada en operaciones mineras. La habilidad invoca a Reno Minero para lanzar un ataque cargado contra los enemigos e infligir un 237,6 % de daño Electro." },
  "Reminiscence - Kronaclaw": { desc: "Una reminiscencia del temible Kronaclaw. La habilidad se transforma en Kronaclaw para elevarse por los aires e infligir un 8,04 % de daño Aero hasta 8 veces y un 24,13 % de daño Aero 2 veces, y luego descender en picado para infligir un 155,55 % de daño Aero una vez." },
  "Kronablight": { desc: "Una variante corrompida del Kronaclaw. La habilidad se transforma en Kronalcón, se eleva por los aires y desciende en picado para infligir un 268,2 % de daño Electro." },
  "Pilgrim's Shell": { desc: "Una criatura peregrina con caparazón. La habilidad se transforma en Peregrino Degradado para atacar a los enemigos cercanos e infligir un 268,2 % de daño Aero." },
  "Kerasaur": { desc: "Un saurio con cuernos de las Mesetas Sanguis. La habilidad se transforma en Kerasaurio para saltar y estrellarse con un 268,2 % de daño Aero; poco después, lanza de nuevo la habilidad de Eco para cargar contra el objetivo con otro 268,2 % de daño Aero. En la ranura principal otorga +12 % de daño Aero y +12 % de daño de liberación de resonancia." },
  "Hurriclaw": { desc: "Una bestia de garras que domina el viento. La habilidad se transforma en Ciclógarra para cargar hacia delante e infligir un 156,6 % de daño Aero al impactar más un barrido de 156,6 % de daño Aero. Mantén pulsado para seguir cargando, o usa de nuevo la habilidad de Eco durante la carga para barrer." },
  "Nightmare: Viridblaze Saurian": { desc: "Una variante pesadilla del saurio que escupe fuego. La habilidad lo invoca para escupir fuego de forma continua e infligir un 17,12 % de daño Fusión 10 veces." },
  "Nightmare: Violet-Feathered Heron": { desc: "Una variante pesadilla de la garza de alas moradas. La habilidad adopta una Postura de parada; el contraataque inflige un 288 % de daño Electro. Si es atacada durante la parada, contraataca antes con un tajo de ala de rayo y recupera 5 de energía de Concierto." },
  "Nightmare: Cyan-Feathered Heron": { desc: "Una variante pesadilla de la garza de alas cian. La habilidad se transforma para cargar contra los enemigos e infligir un 236,8 % de daño Aero; esta habilidad de Eco interrumpe las habilidades especiales enemigas al impactar." },
  "Nightmare: Roseshroom": { desc: "Una variante pesadilla de la criatura fúngica oscura. La habilidad la invoca para disparar un láser que inflige un 57,07 % de daño Destrucción hasta 3 veces." },
  "Nightmare: Tambourinist": { desc: "Una variante pesadilla del que convierte el ritmo en arma sonora. La habilidad lo invoca para tocar Melodías de aniquilación; cualquier miembro del equipo que obtenga una Melodía inflige un 14,4 % adicional de daño Destrucción a su objetivo al impactar, hasta 10 veces durante 10 s." },
  "Diurnus Knight": { desc: "Un caballero diurno de la Orden. La habilidad se transforma en Caballero de Crepúsculo para cargar hacia delante y atacar con la espada con un 268,2 % de daño Espectro. El daño infligido a enemigos afectados por Espectro estridente aumenta un 100 %." },
  "Nocturnus Knight": { desc: "Un caballero nocturno de la Orden. La habilidad se transforma en Caballero de Penumbra para golpear desde el aire a los enemigos de enfrente e infligir un 268,2 % de daño Destrucción." },
  "Questless Knight": { desc: "Un caballero errante sin misión. La habilidad se transforma en Caballero Vagabundo para aplastar a los enemigos circundantes con un 313,2 % de daño Electro." },
  "Abyssal Gladius": { desc: "Un guerrero armado con espada del abismo. La habilidad se transforma en Gladius Abisal para atacar a los enemigos con la espada con un 268,2 % de daño Glacio. Mantén pulsado para conservar la forma de Eco, tajando y lanzando un ataque a distancia hacia delante con un 268,2 % y un 670,5 % de daño Glacio respectivamente." },
  "Abyssal Patricius": { desc: "Un guerrero noble del abismo. La habilidad se transforma en Patricius Abisal para cargar hacia delante e infligir un 268,2 % de daño Glacio. La ranura principal otorga +12 % de bonificación de daño Glacio." },
  "Rage Against the Statue": { desc: "Una estatua animada llena de ira. La habilidad se transforma para atacar a los enemigos con un 313,2 % de daño Espectro. Mantén pulsado para conservar la forma y cargar contra los enemigos con un 469,8 % de daño Espectro." },
  "Vitreum Dancer": { desc: "Un bailarín de aspecto vítreo que canaliza electricidad. La habilidad se transforma en Bailarina Vítrea para atacar a los enemigos circundantes con un 313,2 % de daño Electro. La ranura principal otorga +12 % de bonificación de daño Electro." },
  "Cuddle Wuddle": { desc: "Una criatura engañosamente achuchable. La habilidad se transforma en Mazo Abrazo para 4 golpes que infligen un 46,98 % de daño Físico cada uno, y un golpe final que inflige un 125,28 % de daño Físico." },
  "Chop Chop": { desc: "Un constructo troceador de múltiples brazos. La habilidad invoca a Flotán para una serie de ataques: los primeros 6 golpes infligen un 19,26 % de daño Fusión cada uno y el golpe final un 77,04 % de daño Fusión." },
  "Lightcrusher": { desc: "Un constructo aplastador imbuido de luz. La habilidad se transforma en Correluces y se lanza hacia delante con un 135,36 % de daño Espectro, generando 6 Ablución al impactar; cada explosión de Ablución inflige un 15,04 % de daño Espectro. Mantén pulsado para conservar la forma de Correluces y saltar/abalanzarte hacia delante." },
  "Rocksteady Guardian": { desc: "Un firme guardián de roca. La habilidad se transforma en un Estado de parada; al ser atacado, inflige daño Espectro igual al 8,29 % de los PV máx. con un ataque posterior de otro 8,29 %. Si el ataque es una habilidad especial, la interrumpe, obtiene un Escudo del 30 % de los PV máx. y desata un ataque posterior en dos fases (5,52 % de los PV máx. cada una) más tres ondas rompesuelos (4,59 % de los PV máx. cada una)." },
  "Smiter": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Noqueador para golpear a los enemigos 7 veces con un 19,26 % de daño Espectro cada una, terminando con un gancho de 57,78 % de daño Espectro." },
  "Porcelain Picket": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Guardián de Porcelana para tajar hacia delante, infligiendo 2 golpes de 19,44 % de daño Aero y 7 golpes de 12,96 % de daño Aero a los enemigos en su trayectoria." },
  "Stone Picket": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Guardián Pétreo e inflige un 129,60 % de daño Aero." },
  "Aureate Picket": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad se transforma en un Guardián de Bronce, recuperando PV con el tiempo antes de golpear a los enemigos con un 153,90 % de daño Aero." },
  "Kernel Puppet: Joy": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Títere Anímico: Felicidad para atacar a los enemigos e infligir un 129,60 % de daño Físico." },
  "Kernel Puppet: Anger": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Títere Anímico: Ira para atacar a los enemigos e infligir un 129,60 % de daño Fusión." },
  "Kernel Puppet: Worry": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Títere Anímico: Desasosiego para atacar a los enemigos e infligir un 64,80 % de daño Glacio." },
  "Kernel Puppet: Reflection": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Títere Anímico: Reflexión para atacar a los enemigos e infligir un 64,80 % de daño Electro." },
  "Kernel Puppet: Grief": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Títere Anímico: Tristeza para atacar a los enemigos e infligir un 129,60 % de daño Espectro." },
  "Kernel Puppet: Fright": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Títere Anímico: Terror para atacar a los enemigos e infligir un 51,84 % de daño Destrucción y luego un 77,76 % de daño Destrucción." },
  "Fog Lionarch: Body": { desc: "Un fragmento de bestia de clase Élite de la Tierra de Xuanfang. La habilidad invoca a León Neblinoso: Cuerpo para embestir a los enemigos e infligir un 192,60 % de daño Fusión." },
  "Fog Lionarch: Head": { desc: "Un fragmento de bestia de clase Élite de la Tierra de Xuanfang. La habilidad invoca a León Neblinoso: Cabeza para lanzarse hacia los enemigos e infligir un 129,60 % de daño Fusión." },
  "Smolder": { desc: "Una marioneta de clase Élite de la Tierra de Xuanfang. La habilidad invoca a Candente para lanzar una bola de fuego con un 192,60 % de daño Fusión; si toca el suelo, explota infligiendo otro 192,60 % de daño Fusión a los enemigos en el área." },
  "Electro Predator": { desc: "Una ágil Discordia Tácita humanoide con proyectiles eléctricos. La habilidad invoca a Depredador Eléctrico para disparar 5 veces: las primeras 4 infligen un 17 % de daño Electro y la última un 46 % de daño Electro." },
  "Fusion Dreadmane": { desc: "Una Discordia Tácita Aullador leonina y ardiente. La habilidad invoca a Lobo de Fusión para golpear ferozmente al enemigo e infligir un 32 % + 64 de daño Fusión." },
  "Lava Larva": { desc: "Una pequeña criatura fundida que arde sin cesar. La habilidad invoca a Bichofuego para atacar continuamente a los enemigos infligiendo un 38 % de daño Fusión por golpe. Desaparece cuando el invocador cambia de personaje o se aleja demasiado." },
  "Whiff Whaff": { desc: "Una Discordia Tácita humanoide flotante que manipula el viento. La habilidad invoca a Whiff Whaff para una explosión de aire (51 % de daño Aero) que crea una Zona de baja presión que atrae a los enemigos durante 2 s, infligiendo un 19 % de daño Aero hasta 6 veces." },
  "Cruisewing": { desc: "Una amable Discordia Tácita aviar. La habilidad invoca a Alitaveloz para curar a todos los miembros del equipo un 1,8 % de los PV máx. + 80 PV, hasta 4 veces." },
  "Chirpuff": { desc: "Una pequeña criatura esponjosa que se infla con aire. La habilidad invoca a Chirriajín para soplar 3 potentes ráfagas hacia delante, cada una con un 38 % de daño Aero, que empujan a los enemigos hacia atrás." },
  "Fusion Warrior": { desc: "Una Discordia Tácita humanoide envuelta en llamas. La habilidad se transforma en Guerrero de Fusión para realizar un Contraataque. Un contraataque exitoso reduce la reutilización un 70 % e inflige un 288 % de daño Fusión." },
  "Havoc Warrior": { desc: "Una Discordia Tácita humanoide envuelta en energía de Destrucción. La habilidad se transforma en Guerrero de Destrucción para realizar un Contraataque. Un contraataque exitoso reduce la reutilización un 70 % e inflige un 288 % de daño Destrucción." },
  "Snip Snap": { desc: "Una Discordia Tácita humanoide inmadura que exuda pequeñas cantidades de magma. La habilidad invoca a Snip Snap para lanzar bolas de fuego que infligen un 32 % + 64 de daño Fusión al impactar." },
  "Zig Zag": { desc: "Una Discordia Tácita humanoide inmadura que emite rayos de luz concentrados con un sonido de «zig zag». La habilidad invoca a Zig Zag para detonar energía Espectro con un 48 % + 96 de daño Espectro, creando una Zona de estancamiento durante 1,8 s." },
  "Hooscamp": { desc: "Una pequeña Discordia Tácita parecida a un primate. La habilidad se transforma en Campemico Flinger y se abalanza sobre los enemigos infligiendo un 48 % + 96 de daño Aero." },
  "Fusion Prism": { desc: "Una Discordia Tácita mineral llena de energía térmica. La habilidad invoca a Prisma de Fusión para disparar un fragmento de cristal que inflige un 32 % + 64 de daño Fusión." },
  "Glacio Prism": { desc: "Una Discordia Tácita mineral llena de energía gélida. La habilidad invoca a Prisma Gélido para disparar 3 fragmentos de cristal, cada uno con un 38 % de daño Glacio." },
  "Aero Prism": { desc: "Una Discordia Tácita mineral llena de potentes corrientes de aire. La habilidad invoca a Prisma Eólico para atacar a los enemigos infligiendo un 19 % de daño Aero." },
  "Havoc Prism": { desc: "Una Discordia Tácita mineral llena de energía de Destrucción. La habilidad invoca a Prisma de Destrucción para disparar 5 fragmentos de cristal, cada uno con un 23 % de daño Destrucción." },
  "Spectro Prism": { desc: "Una Discordia Tácita mineral que emite luz Espectro para potenciar a los aliados cercanos. La habilidad invoca a Prisma de Espectro para emitir un láser que impacta hasta 8 veces con un 14 % de daño Espectro cada una." },
  "Baby Viridblaze Saurian": { desc: "Una pequeña criatura anfibia de los bosques. La habilidad se transforma en Saurio Viridblaze Bebé para descansar en el sitio y restaurar PV lentamente." },
  "Baby Roseshroom": { desc: "Una joven Discordia Tácita fúngica. La habilidad invoca a Champirosita para disparar un láser que inflige un 32 % + 64 de daño Destrucción." },
  "Clang Bang": { desc: "Una Discordia Tácita humanoide inmadura con cristales de hielo que suenan «clang bang». La habilidad invoca a Clang Bang, que sigue al enemigo y se autodestruye infligiendo un 32 % + 64 de daño Glacio." },
  "Dwarf Cassowary": { desc: "Una pequeña Discordia Tácita parecida a un ave no voladora. La habilidad invoca a Casuario Enano para rastrear y atacar al enemigo infligiendo un 38 % de daño Físico x3." },
  "Excarat": { desc: "Una Discordia Tácita roedora excavadora. La habilidad se transforma en Excarrata y avanza excavando bajo tierra, inmune al daño mientras está enterrado. Puede cambiar de dirección libremente." },
  "Lottie Lost": { desc: "Una pequeña y caprichosa Discordia Tácita que vaga sin rumbo. La habilidad invoca a Lottie Silente para atacar a los enemigos e infligir un 129,6 % de daño Espectro." },
  "Chest Mimic": { desc: "Una Discordia Tácita engañosa disfrazada de cofre del tesoro. La habilidad invoca a Cofre Mímico para atacar con 3 golpes consecutivos, cada uno con un 64,19 % de daño Espectro." },
  "Aero Predator": { desc: "Una ágil Discordia Tácita humanoide que dispara proyectiles de aire. La habilidad invoca a Depredador Eólico para lanzar un dardo que rebota entre enemigos hasta 3 veces, infligiendo un 28,8 % de daño Aero por impacto." },
  "Glacio Predator": { desc: "Una ágil Discordia Tácita humanoide que dispara proyectiles de hielo. La habilidad invoca a Depredador Gélido para lanzar una lanza de hielo que inflige un 46,08 % de daño Glacio al impactar, más un 4,61 % de daño Glacio hasta 10 veces durante la carga y un 23,04 % de daño Glacio cuando la lanza explota." },
  "Gulpuff": { desc: "Una Discordia Tácita que sopla burbujas. La habilidad invoca a Burbujín para soplar burbujas 5 veces, cada una con un 23,04 % de daño Glacio." },
  "Aero Drake": { desc: "Un draco elemental de viento. La habilidad invoca a Draco Eólico para atacar a los enemigos e infligir un 129,6 % de daño Aero." },
  "Electro Drake": { desc: "Un draco elemental de rayo. La habilidad invoca a Draco Eléctrico para atacar a los enemigos e infligir un 43,2 % de daño Electro 3 veces." },
  "Fusion Drake": { desc: "Un draco elemental de fuego. La habilidad invoca a Draco Fusión para atacar a los enemigos e infligir un 25,92 % de daño Fusión 3 veces." },
  "Glacio Drake": { desc: "Un draco elemental de hielo. La habilidad invoca a Draco Gélido para atacar a los enemigos e infligir un 25,92 % de daño Glacio 5 veces." },
  "Havoc Drake": { desc: "Un draco elemental de Destrucción. La habilidad invoca a Draco Destrucción para atacar a los enemigos e infligir un 129,6 % de daño Destrucción 3 veces." },
  "Spectro Drake": { desc: "Un draco elemental de Espectro. La habilidad invoca a Draco Espectro para atacar a los enemigos e infligir un 43,2 % de daño Espectro 3 veces." },
  "Devotee's Flesh": { desc: "Una criatura devota nacida de una devoción fanática. La habilidad invoca a Devoto Corrupto para atacar a los enemigos e infligir un 43,2 % de daño Aero 3 veces." },
  "Sacerdos": { desc: "Una criatura sacerdotal que entona himnos de viento. La habilidad invoca a Sacerdos para atacar a los enemigos e infligir un 64,8 % de daño Aero 2 veces." },
  "Sagittario": { desc: "Una criatura arquera que dispara flechas de luz. La habilidad se transforma en Sagittario para moverse y disparar un ataque a distancia con un 268,2 % de daño Espectro. Ser atacado mientras se mueve activa un Contraataque de esquiva, que inflige un 268,2 % de daño Espectro una vez y un 53,64 % de daño Espectro 5 veces." },
  "La Guardia": { desc: "Una vigilante criatura guardiana que empuña un escudo de piedra. La habilidad se transforma en La Guardia para atacar a los objetivos cercanos con un 268,2 % de daño Físico. Mantén pulsado para conservar la forma de Eco: un tajo inflige otro 268,2 % de daño Físico y un ataque a distancia inflige hasta 15 golpes de 17,87 % de daño Físico." },
  "Calcified Junrock": { desc: "Una variante calcificada de Junrock endurecida por depósitos minerales. La habilidad invoca a Junroca Calcificada, que restaura PV a los miembros del equipo cercanos equivalentes al 2,52 % de sus PV máx., hasta 5 veces." },
  "Fission Junrock": { desc: "Un Junrock impulsado por fisión que irradia energía cálida. La habilidad invoca a Junroca Fisión, generando un Efecto de resonancia que restaura un 2 % de los PV máx. a las unidades aliadas cada vez. Fuera de combate, también puede recoger minerales o plantas cercanos." },
  "Golden Junrock": { desc: "Una variante dorada de Junrock que brilla con luz espectral. La habilidad invoca a Junroca Dorada para cargar hacia delante e infligir un 129,6 % de daño Espectro a los enemigos en su camino." },
  "Vanguard Junrock": { desc: "Una variante de vanguardia de Junrock acorazada con placas de roca. La habilidad invoca a Junroca Vanguardia para cargar hacia delante e infligir daño Físico a los enemigos en su camino." },
  "Diamondclaw": { desc: "Una criatura de garras de diamante con zarpas cristalinas afiladas como cuchillas. La habilidad se transforma en Crystal Scorpion y entra en un Estado de parada; contraataca cuando termina el Estado de parada, infligiendo daño Físico." },
  "Diggy Duggy": { desc: "Una criatura excavadora que ataca desde el subsuelo. La habilidad se transforma en Pico Pala y salta por los aires para estrellarse contra los enemigos e infligir un 268,2 % de daño Físico." },
  "Fae Ignis": { desc: "Una criatura de llama feérica que parpadea con fuego oscuro. La habilidad invoca a Fae Ígneo para atacar a los enemigos e infligir un 129,6 % de daño Destrucción." },
  "Frostscourge Stalker": { desc: "Un acechador imbuido de escarcha que caza en terrenos helados. La habilidad invoca a Lobo Escarchado para atacar a los enemigos e infligir un 129,6 % de daño Glacio." },
  "Voltscourge Stalker": { desc: "Un acechador imbuido de voltaje que crepita de estática. La habilidad invoca a Lobo de Trueno para realizar 3 fases de ataques contra los enemigos, cada una con un 43,2 % de daño Electro." },
  "Galescourge Stalker": { desc: "Un acechador imbuido de vendaval que se mueve con el viento. La habilidad invoca a Lobo de Huracán, que restaura PV a los miembros del grupo cercanos equivalentes al 2,7 % de sus PV máx., hasta 3 veces." },
  "Hocus Pocus": { desc: "Una criatura embaucadora mágica envuelta en ilusiones oscuras. La habilidad invoca a Abra Cadabra para atacar a los enemigos con 3 golpes consecutivos, cada uno con un 43,2 % de daño Destrucción." },
  "Nimbus Wraith": { desc: "Un espectro similar a una nube que flota entre la bruma. La habilidad invoca a Espectro de Nimbo, que restaura PV al Resonador activo equivalentes al 2,7 % de sus PV máx., hasta 4 veces." },
  "Hoartoise": { desc: "Una criatura tortuga cana con el caparazón cubierto de escarcha. La habilidad se transforma en Escartuga y restaura PV lentamente. Usa de nuevo la habilidad de Eco para salir de la transformación." },
  "Sabyr Boar": { desc: "Una criatura jabalí con colmillos que embiste con fuerza temeraria. La habilidad invoca a Jabalí Sabyr para lanzar al enemigo por los aires de un cabezazo, infligiendo daño Físico." },
  "Traffic Illuminator": { desc: "Un constructo similar a un semáforo que emite señales de advertencia. La habilidad invoca a Semaforoide, que inmoviliza a los enemigos hasta 1 s; la inmovilización se levanta en cuanto el enemigo recibe un golpe. No inflige daño directo." },
  "Tick Tack": { desc: "Una criatura similar a un reloj cuyas manecillas giran erráticamente. La habilidad invoca a Tic Tac para cargar y morder al enemigo, infligiendo un 68,48 % de daño Destrucción en la carga y un 102,72 % de daño Destrucción con la mordedura, y reduciendo la Fuerza de vibración del enemigo hasta un 5 % durante 5 s." },
  "Chop Chop: Headless": { desc: "El cuerpo sin cabeza de Chop Chop, que golpea a ciegas. La habilidad invoca a Flotán: Testa para atacar a los enemigos e infligir un 129,6 % de daño Fusión." },
  "Chop Chop: Leftless": { desc: "Chop Chop sin el brazo izquierdo, que lo compensa con energía espectral. La habilidad invoca a Flotán: Siniestra para atacar a los enemigos e infligir un 129,6 % de daño Espectro." },
  "Chop Chop: Rightless": { desc: "Chop Chop sin el brazo derecho, que filtra energía de Destrucción. La habilidad invoca a Flotán: Diestra para atacar a los enemigos e infligir un 129,6 % de daño Destrucción." },
  "Geospider S4": { desc: "Una araña mecánica de Lahai-Roi. La habilidad invoca a Geoaraña S4 para atacar a los enemigos, infligiendo un 51,84 % de daño Espectro una vez y un 77,76 % de daño Espectro otra vez." },
  "Flora Drone": { desc: "Un dron botánico de Lahai-Roi. La habilidad invoca a Dron Floral, que inflige un 64,8 % de daño Aero a los enemigos y cura a los Resonadores en su radio un 3,6 % de los PV máx. + 160." },
  "Mining Drone": { desc: "Un dron minero de Lahai-Roi. La habilidad se transforma en Dron Minero para atacar a los enemigos e infligir un 102,6 % de daño Destrucción dos veces." },
  "Zip Zap": { desc: "Una criatura eléctrica de Lahai-Roi. La habilidad invoca a Zip Zap para lanzar ataques giratorios contra los enemigos e infligir un 25,92 % de daño Electro 5 veces." },
  "Iceglint Dancer": { desc: "Un bailarín cristalino que gira sobre cuchillas de hielo. La habilidad se transforma en Bailarina Geliófila para atacar a los enemigos e infligir un 205,2 % de daño Glacio." },
  "Shadow Stepper": { desc: "Una criatura que camina entre sombras y atraviesa la oscuridad. La habilidad invoca a Caminante Sombrío para atacar a los enemigos e infligir un 129,6 % de daño Destrucción." },
  "Tremor Warrior": { desc: "Un guerrero que provoca temblores y canaliza electricidad sísmica. La habilidad se transforma en Guerrero Escalofrío para atacar a los enemigos de enfrente e infligir un 205,2 % de daño Electro." },
  "Nightmare: Aero Predator": { desc: "Una variante pesadilla del Aero Predator con proyectiles de viento mejorados. La habilidad lo invoca para lanzar un dardo que rebota entre enemigos hasta 3 veces, infligiendo un 28,8 % de daño Aero por impacto." },
  "Nightmare: Electro Predator": { desc: "Una variante pesadilla del Electro Predator con rayos sobrecargados. La habilidad lo invoca para disparar al enemigo 5 veces: los primeros 4 disparos infligen un 17,28 % de daño Electro y el último un 46,08 % de daño Electro." },
  "Nightmare: Glacio Predator": { desc: "Una variante pesadilla del Glacio Predator con esquirlas de hielo perforantes. La habilidad lo invoca para lanzar una lanza de hielo que inflige un 46,08 % de daño Glacio al impactar, más un 4,61 % de daño Glacio hasta 10 veces durante la carga y un 23,04 % de daño Glacio cuando la lanza explota." },
  "Nightmare: Baby Roseshroom": { desc: "Una variante pesadilla del Baby Roseshroom con esporas amplificadas. La habilidad lo invoca para disparar un láser que inflige daño Destrucción." },
  "Nightmare: Baby Viridblaze Saurian": { desc: "Una variante pesadilla del Baby Viridblaze Saurian envuelta en llama oscura. La habilidad se transforma en el saurio para descansar en el sitio y restaurar PV lentamente." },
  "Nightmare: Chirpuff": { desc: "Una variante pesadilla de Chirpuff inflada en exceso con viento de pesadilla. La habilidad lo invoca para inflarse y soplar 3 ráfagas de viento hacia delante, cada una con un 38,4 % de daño Aero, que empujan a los enemigos hacia atrás." },
  "Nightmare: Dwarf Cassowary": { desc: "Una variante pesadilla del Dwarf Cassowary con plumas afiladas como cuchillas. La habilidad lo invoca para rastrear y atacar al enemigo infligiendo un 38,4 % de daño Físico 3 veces." },
  "Nightmare: Gulpuff": { desc: "Una variante pesadilla de Gulpuff que exhala bruma helada. La habilidad lo invoca para soplar burbujas 5 veces, cada una con un 23,04 % de daño Glacio." },
  "Nightmare: Havoc Warrior": { desc: "Una variante pesadilla del Havoc Warrior que irradia energía oscura. La habilidad se transforma en Pesadilla: Guerrero de Destrucción para atacar hasta 3 veces, infligiendo un 171,73 % de daño Destrucción cada vez." },
  "Nightmare: Tick Tack": { desc: "Una variante pesadilla de Tick Tack cuyo tictac distorsiona el tiempo. La habilidad lo invoca para cargar y morder al enemigo, infligiendo un 68,48 % de daño Destrucción en la carga y un 102,72 % de daño Destrucción con la mordedura, y reduciendo la Fuerza de vibración del enemigo hasta un 5 % durante 5 s." },
};

const BUFF_ES = {
  'Spectro DMG': 'Daño Espectro', 'Aero DMG': 'Daño Aero', 'Electro DMG': 'Daño Electro', 'Fusion DMG': 'Daño Fusión',
  'Havoc DMG': 'Daño Destrucción', 'Glacio DMG': 'Daño Glacio', 'Physical DMG': 'Daño Físico',
  Shield: 'Escudo', Healing: 'Curación', Utility: 'Utilidad',
};

/** @param {string|string[]} buff */
export function translateBuffEs(buff) {
  const one = (b) => BUFF_ES[b] || b;
  return Array.isArray(buff) ? buff.map(one) : one(buff);
}

